//! Generating and hashing the server's bearer secrets: the admin token,
//! enrollment tokens, and machine credentials.
//!
//! Secrets are 256 random bits, so a plain SHA-256 is enough to store them;
//! there is nothing to brute-force.

use base64::Engine;
use sha2::{Digest, Sha256};

/// Prefix of one-time enrollment tokens.
pub const ENROLLMENT_TOKEN_PREFIX: &str = "mnix_enroll_";
/// Prefix of machine credentials.
pub const CREDENTIAL_PREFIX: &str = "mnix_cred_";
/// Prefix of admin tokens generated by the server.
pub const ADMIN_TOKEN_PREFIX: &str = "mnix_admin_";

/// A new random secret with the given prefix (which makes leaked secrets
/// easy to recognise).
pub fn generate(prefix: &str) -> String {
    let mut bytes = [0u8; 32];
    getrandom::fill(&mut bytes).expect("the OS random number generator is available");
    format!(
        "{prefix}{}",
        base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(bytes)
    )
}

/// The hex SHA-256 of a secret, which is what the database stores.
pub fn hash(secret: &str) -> String {
    Sha256::digest(secret.as_bytes())
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

/// The bearer token from an `Authorization` header value.
pub fn bearer(header: &str) -> Option<&str> {
    let (scheme, token) = header.split_once(' ')?;
    scheme
        .eq_ignore_ascii_case("bearer")
        .then(|| token.trim())
        .filter(|t| !t.is_empty())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn secrets_are_random_and_prefixed() {
        let a = generate(CREDENTIAL_PREFIX);
        let b = generate(CREDENTIAL_PREFIX);
        assert_ne!(a, b);
        assert!(a.starts_with(CREDENTIAL_PREFIX));
        assert_eq!(a.len(), CREDENTIAL_PREFIX.len() + 43);
    }

    #[test]
    fn hashes_are_hex_sha256() {
        assert_eq!(
            hash("abc"),
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
        );
    }

    #[test]
    fn parses_bearer_headers() {
        assert_eq!(bearer("Bearer abc"), Some("abc"));
        assert_eq!(bearer("bearer  abc "), Some("abc"));
        assert_eq!(bearer("Basic abc"), None);
        assert_eq!(bearer("Bearer "), None);
        assert_eq!(bearer("abc"), None);
    }
}
